import { FITTED_GAME_VARIANCE } from "./game-variance-fitted";
import type { GameVariancePriors } from "./game-variance";
import { FITTED_KDEF_GAME_VARIANCE } from "./kdef-fitted";

/**
 * THE ONE PLACE THE TWO HALVES OF THE PER-GAME VARIANCE TABLE ARE COMPOSED (the 2026-09-05 kicker
 * and team defence round).
 *
 * The table is generated by two different scripts because it is measured from two different stores,
 * and neither script can produce the other's cells. `game-variance-fit.ts` reads
 * `player_week_observations`, which holds the four skill positions and has never held a kicker row
 * or a team-defence row. `kdef-fit.ts` reads the kicking and team-defence archives, which hold
 * nothing else. Having each own its own generated file and composing them here beats having one
 * script write cells it cannot measure, which is exactly how a fabricated zero gets shipped.
 *
 * A HAND-WRITTEN FILE ON PURPOSE, and a small one: both inputs are generated and must not be edited,
 * so the composition needs somewhere to live that a regeneration will not overwrite. There is no
 * key collision to resolve — the two sides carry disjoint positions — and a test asserts that stays
 * true, because a silent overwrite here would replace a measured cell with another measured cell and
 * look like nothing at all.
 */
export const SHIPPED_GAME_VARIANCE: GameVariancePriors = {
  rookie: { ...FITTED_GAME_VARIANCE.rookie, ...FITTED_KDEF_GAME_VARIANCE.rookie },
  veteran: { ...FITTED_GAME_VARIANCE.veteran, ...FITTED_KDEF_GAME_VARIANCE.veteran },
};
